<?php
geo_system_required();$tab=($_GET['tab']??'officers')==='teams'?'teams':'officers';
$search=trim(substr((string)($_GET['search']??''),0,160));$province=max(0,(int)($_GET['province']??0));$district=max(0,(int)($_GET['district']??0));$town=max(0,(int)($_GET['town']??0));
$w=['u.role=?'];$params=[$tab==='teams'?'maintenance':'officer'];
if($search!==''){$w[]='(u.name LIKE ? OR u.email LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}
if($province){$w[]='p.id=?';$params[]=$province;}if($district){$w[]='d.id=?';$params[]=$district;}if($town){$w[]=$tab==='teams'?'t.id=?':'EXISTS(SELECT 1 FROM geo_towns ft WHERE ft.district_id=d.id AND ft.id=?)';$params[]=$town;}
$joins=$tab==='teams'?' LEFT JOIN geo_towns t ON t.id=u.town_id LEFT JOIN geo_districts d ON d.id=t.district_id':' LEFT JOIN geo_districts d ON d.officer_id=u.id';
$from=' FROM users u'.$joins.' LEFT JOIN geo_provinces p ON p.id=d.province_id WHERE '.implode(' AND ',$w);
$total=(int)q('SELECT COUNT(*)'.$from,$params)->fetchColumn();$pages=max(1,(int)ceil($total/15));$pn=min($pages,max(1,(int)($_GET['p']??1)));
$owner=$tab==='teams'?'maintenance_id':'officer_id';
$rows=q('SELECT u.id,u.name,u.active,p.name province,d.name district,d.id district_id,'.($tab==='teams'?'t.name town,':'')."(SELECT COUNT(*) FROM issues i WHERE i.$owner=u.id AND i.status NOT IN ('Resolved','Rejected','Duplicate')) workload,(SELECT COUNT(*) FROM issues i WHERE i.$owner=u.id AND i.maintenance_stage='Review' AND i.status IN ('Assigned','In Progress')) review".$from.' ORDER BY workload DESC,u.name,u.id LIMIT 15 OFFSET '.(($pn-1)*15),$params)->fetchAll();
admin_page_start('Districts & workload','Compare District Officer and town maintenance workloads. Responsibility is set in Province routing.');admin_tabs('areas',['officers'=>'District Officers','teams'=>'Maintenance teams'],$tab);
?><form method="get" class="panel regional-workload-filters"><input type="hidden" name="page" value="areas"><input type="hidden" name="tab" value="<?=e($tab)?>"><label>Search name or email<input type="search" name="search" maxlength="160" value="<?=e($search)?>" placeholder="Officer or team name"></label><?php geo_filter_controls(['province'=>$province,'district'=>$district,'town'=>$town]);?><div class="row"><button class="button secondary">Apply filters</button><a class="text-link" href="index.php?page=areas&amp;tab=<?=e($tab)?>">Reset</a><a class="text-link" href="index.php?page=routing">Manage routing responsibility →</a></div></form>
<section class="panel section-space"><h2><?=$total?> matching <?=$tab==='teams'?'maintenance teams':'District Officers'?></h2><p class="small muted">Open workload includes reports awaiting final approval. A missing mapping does not grant unrestricted geographical access. Disabled accounts remain visible for handover review.</p><?php if(!$rows):?><p class="small muted">No accounts match these filters.</p><?php else:?><div class="table-wrap"><table><thead><tr><th><?=$tab==='teams'?'Team':'Officer'?></th><th>Province</th><th>District<?=$tab==='teams'?' / Town':''?></th><th>Access</th><th>Open work</th><th>Officer reviews</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['name'])?></td><td><?=e($row['province']?:'Not configured')?></td><td><?=e($row['district']?:'Not configured')?><?php if($tab==='teams'):?><br><small><?=e($row['town']?:'Town not configured')?></small><?php endif;?></td><td><?=badge($row['active']?'Active':'Disabled')?></td><td><?=(int)$row['workload']?></td><td><?=(int)$row['review']?></td><td><a class="text-link" href="index.php?page=reports&amp;<?=$tab==='teams'?'team':'officer'?>=<?=(int)$row['id']?>">View reports →</a><?php if(!$row['district_id']):?><br><a class="text-link" href="index.php?page=routing&amp;tab=accounts&amp;mapping=<?=$tab==='teams'?'town':'district'?>&amp;user_id=<?=(int)$row['id']?>">Configure responsibility →</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;admin_pager($pn,$pages,$total);?></section>
<?php admin_page_end();
